# Card data: real experience step-by-step (PRIMARY). Synthetic study content only.
# Intended importer (future regenerator): from cards_experience import CARDS
# Shape: {sec, kind, title, sub, c_en, m_en, c_vi, m_vi, crib?, note?} — no date fields.
# Honesty: Akktis full-stack+DevOps (Linux SSH, CI/CD multi-env mobile+web, GCP Cloud Run/SQL/Storage,
# LiteSpeed/Apache, docs/hardening) + IELTS AI Tutor (RN/TS iOS/Android, Cloud Run, store publish).


def C(sec, title, sub, c_en, m_en, c_vi, m_vi, crib="", note=""):
    return {"sec": sec, "kind": "concept", "title": title, "sub": sub,
            "c_en": c_en, "m_en": m_en, "c_vi": c_vi, "m_vi": m_vi,
            "crib": crib, "note": note}


def S(sec, title, sub, c_en, m_en, c_vi, m_vi, crib="", note=""):
    """Step card — same shape as concept; use for numbered procedures."""
    return C(sec, title, sub, c_en, m_en, c_vi, m_vi, crib, note)


